function tree(x, z, size = 1) {
  const g = new THREE.Group();
  g.position.set(x, 0, z);
  g.userData = { breakable: true, hp: 6, kind: 'tree' };
  cube(g, 0, size * .9, 0, .4 * size, 1.8 * size, .4 * size, materials.wood);
  for (let i = 0; i < 3; i++) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(1.7 * size, 1.25 * size, 1.7 * size), i % 2 ? materials.leaf : materials.leaf2);
    m.position.set(0, (1.8 + i * .55) * size, 0);
    m.rotation.y = rand(0, 1);
    m.castShadow = true;
    m.receiveShadow = true;
    g.add(m);
  }
  world.add(g);
  decor.push(g);
  return g;
}
function shrub(x, z) {
  const g = new THREE.Group();
  g.position.set(x, .35, z);
  g.userData = { breakable: true, hp: 2, kind: 'shrub' };
  for (let i = 0; i < 4; i++) {
    const c = cube(g, rand(-.35, .35), rand(-.1, .2), rand(-.3, .3), .45, .45, .45, i % 2 ? materials.leaf : materials.leaf2);
    c.rotation.y = rand(0, 3);
  }
  world.add(g);
  decor.push(g);
}
function vehicle(x, z) {
  const g = new THREE.Group();
  g.position.set(x, 0, z);
  g.userData = { breakable: true, hp: 14, kind: 'vehicle' };
  cube(g, 0, .55, 0, 3.8, .72, 1.8, materials.leaf);
  cube(g, -.15, 1.15, 0, 1.8, .75, 1.55, materials.leaf2);
  cube(g, -.15, 1.2, .79, .95, .48, .06, mat('#9cb7a6', .3));
  cube(g, -.15, 1.2, -.79, .95, .48, .06, mat('#9cb7a6', .3));
  cube(g, 1.9, .45, 0, .2, .3, 1.65, materials.steel);
  for (const xx of [-1.25, 1.25]) for (const zz of [-.97, .97]) {
    const tire = new THREE.Mesh(new THREE.CylinderGeometry(.42, .42, .25, 12), materials.black);
    tire.rotation.z = Math.PI / 2;
    tire.position.set(xx, .4, zz);
    tire.castShadow = true;
    g.add(tire);
  }
  world.add(g);
  vehicles.push(g);
  decor.push(g);
  return g;
}
function house(x, z, town = false) {
  const g = new THREE.Group();
  g.position.set(x, 0, z);
  g.userData = { breakable: true, hp: 24, kind: 'house' };
  const wall = mat(town ? '#d8c6a5' : '#adb8a4');
  const roof = mat(town ? '#8f5343' : '#475b4b');
  cube(g, 0, 1.5, 0, 6, 3, 5, wall);
  cube(g, 0, 3.35, 0, 6.6, .6, 5.6, roof);
  cube(g, -1.7, .85, 2.52, .9, 1.7, .08, mat('#604a37'));
  for (const sx of [-1.8, 1.8]) cube(g, sx, 2, 2.55, .9, .8, .08, mat('#91b1ad', .3));
  world.add(g);
  decor.push(g);
}
function applyTheme() {
  const theme = mapThemes[mapIndex];
  scene.background.set(theme.bg);
  scene.fog.color.set(theme.bg);
  scene.fog.near = theme.fogNear;
  scene.fog.far = theme.fogFar;
  materials.path.color.set(mapIndex === 1 ? '#99836a' : '#b9a17c');
}
function buildMap(idx = 0) {
  mapIndex = (idx + 4) % 4;
  world.clear();
  decor = [];
  vehicles = [];
  applyTheme();
  if (mapIndex === 0) {
    makeTerrain();
    path(0, 0, 8, 90);
    path(0, -4, 90, 7, .05);
    for (let i = 0; i < 58; i++) {
      const x = rand(-45, 45);
      const z = rand(-45, 45);
      if (Math.abs(x) < 7 || Math.abs(z) < 6 || Math.hypot(x, z - 15) < 6) continue;
      if (Math.random() < .78) tree(x, z, rand(.72, 1.3));
      else shrub(x, z);
    }
    vehicle(9, -2);
    house(-15, -12, false);
  }
  if (mapIndex === 1) {
    makeTerrain('#84906a');
    path(0, 0, 10, 120);
    path(0, 0, 120, 9);
    for (let x = -32; x <= 32; x += 16) for (let z = -28; z <= 28; z += 18) {
      if (Math.random() > .15 && Math.hypot(x, z - 15) > 7) house(x + rand(-2, 2), z + rand(-2, 2), true);
    }
    for (let i = 0; i < 20; i++) tree(rand(-52, 52), rand(-52, 52), rand(.7, 1));
  }
  if (mapIndex === 2) {
    makeTerrain('#50634c');
    for (let i = 0; i < 90; i++) tree(rand(-48, 48), rand(-48, 48), rand(.8, 1.45));
    path(0, 0, 5, 80);
    for (let i = 0; i < 5; i++) cube(world, rand(-8, 8), .7, rand(-22, 22), rand(1, 2), 1.4, rand(1, 2), materials.wood);
  }
  if (mapIndex === 3) {
    makeTerrain('#77766c');
    for (let i = 0; i < 12; i++) {
      const a = i * Math.PI / 6;
      const wall = cube(world, Math.sin(a) * 18, 1.4, Math.cos(a) * 18, 7, 2.8, .8, mat('#887f6d'));
      wall.rotation.y = a;
    }
    for (let i = 0; i < 6; i++) cube(world, rand(-11, 11), .65, rand(-11, 11), rand(2, 4), 1.3, rand(2, 4), mat('#929187'));
  }
  const names = ['SUNLIT MEADOW', 'DUSTY CROSSING', 'PINE SHADE', 'THE ARENA'];
  document.querySelector('#mapName').textContent = names[mapIndex];
}

