// ---------- Audio ----------
let audioCtx = null;
let masterGain = null;
let noiseBuf = null;
function ensureAudio() {
  if (audioCtx) {
    if (audioCtx.state === 'suspended') audioCtx.resume();
    return;
  }
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return;
  audioCtx = new AC();
  masterGain = audioCtx.createGain();
  masterGain.gain.value = .16;
  masterGain.connect(audioCtx.destination);
}
function getNoise() {
  if (noiseBuf) return noiseBuf;
  const len = audioCtx.sampleRate;
  noiseBuf = audioCtx.createBuffer(1, len, audioCtx.sampleRate);
  const data = noiseBuf.getChannelData(0);
  for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
  return noiseBuf;
}
function noiseBurst(dur = .1, gain = .3, freq = 1200, type = 'lowpass') {
  if (!audioCtx || state.muted) return;
  const src = audioCtx.createBufferSource();
  src.buffer = getNoise();
  const filter = audioCtx.createBiquadFilter();
  filter.type = type;
  filter.frequency.value = freq;
  const g = audioCtx.createGain();
  const now = audioCtx.currentTime;
  g.gain.setValueAtTime(gain, now);
  g.gain.exponentialRampToValueAtTime(.0001, now + dur);
  src.connect(filter).connect(g).connect(masterGain);
  src.start(now);
  src.stop(now + dur + .02);
}
function tone(freq, dur = .1, type = 'sine', gain = .12, slide = 0, delay = 0) {
  if (!audioCtx || state.muted) return;
  const osc = audioCtx.createOscillator();
  const g = audioCtx.createGain();
  const now = audioCtx.currentTime + delay;
  osc.type = type;
  osc.frequency.setValueAtTime(freq, now);
  if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), now + dur);
  g.gain.setValueAtTime(.0001, now);
  g.gain.exponentialRampToValueAtTime(gain, now + .008);
  g.gain.exponentialRampToValueAtTime(.0001, now + dur);
  osc.connect(g).connect(masterGain);
  osc.start(now);
  osc.stop(now + dur + .03);
}
function sfx(name) {
  if (!audioCtx || state.muted) return;
  switch (name) {
    case 'rifle':
      noiseBurst(.09, .34, 2200);
      tone(95, .08, 'square', .1, -35);
      break;
    case 'deagle':
      noiseBurst(.16, .52, 900);
      tone(62, .15, 'sawtooth', .2, -25);
      break;
    case 'shotgun':
      noiseBurst(.24, .68, 750);
      tone(48, .2, 'triangle', .28, -18);
      break;
    case 'flame':
      noiseBurst(.08, .12, 700);
      break;
    case 'guard':
      tone(260, .06, 'square', .08, 80);
      noiseBurst(.05, .1, 1800);
      break;
    case 'katana':
      tone(920, .13, 'triangle', .09, -520);
      noiseBurst(.06, .12, 3000, 'highpass');
      break;
    case 'throw':
      noiseBurst(.18, .16, 500);
      tone(180, .18, 'sine', .06, 120);
      break;
    case 'reload':
      tone(190, .045, 'square', .08);
