      break;
    case 'empty':
      tone(120, .04, 'square', .06);
      break;
    case 'hit':
      tone(620, .045, 'square', .045, -80);
      break;
    case 'death':
      noiseBurst(.3, .35, 400);
      tone(55, .3, 'sawtooth', .14, -20);
      break;
    case 'scream':
      tone(620, .25, 'sawtooth', .035, 420);
      break;
    case 'explosion':
      noiseBurst(.55, .8, 260);
