      break;
    case 'thunder':
      noiseBurst(.28, .5, 1800, 'highpass');
      tone(70, .32, 'sawtooth', .16, -30);
      break;
    case 'push':
      noiseBurst(.18, .2, 800);
      tone(110, .16, 'sine', .09, 80);
      break;
    case 'grab':
      tone(240, .14, 'sine', .08, 380);
      break;
    case 'hurt':
