      break;
    case 'crash':
      noiseBurst(.32, .4, 500);
      tone(70, .18, 'triangle', .12, -20);
      break;
    case 'wood':
      noiseBurst(.16, .24, 900);
      break;
    case 'respawn':
      tone(300, .18, 'sine', .07, 200);
      tone(500, .22, 'sine', .06, 120, .12);
      break;
  }
}

// ---------- Voxel people ----------
function makeVoxelPerson(x, z, civilian = true) {
  const g = new THREE.Group();
  g.position.set(x, 0, z);
  const palette = civilian
    ? [materials.blue, materials.red, materials.cream, materials.yellow, mat('#557c66')]
    : [mat('#4b5c53'), mat('#555c59'), mat('#65665e')];
  const shirt = palette[Math.floor(Math.random() * palette.length)];
  const pants = civilian ? mat(['#364252', '#4f594b', '#524b44'][Math.floor(Math.random() * 3)]) : mat('#303933');
  const skin = mat(['#e0b18a', '#c98e69', '#efc49b', '#8f5e49'][Math.floor(Math.random() * 4)]);
  const parts = [];
  const add = (name, x0, y0, z0, sx, sy, sz, m) => {
    const o = cube(g, x0, y0, z0, sx, sy, sz, m);
    o.userData.part = name;
    parts.push(o);
    return o;
  };
  add('torso', 0, 1.27, 0, .62, .78, .34, shirt);
  add('head', 0, 1.92, 0, .42, .44, .4, skin);
  add('hair', 0, 2.17, -.015, .45, .13, .43, mat(['#3c3028', '#2c2925', '#967044', '#483b30'][Math.floor(Math.random() * 4)]));
  add('face', 0, 1.94, .205, .28, .13, .025, skin);
  add('eyeL', -.09, 2, .225, .045, .045, .025, materials.black);
  add('eyeR', .09, 2, .225, .045, .045, .025, materials.black);
  add('armL', -.43, 1.3, 0, .22, .68, .24, shirt);
  add('armR', .43, 1.3, 0, .22, .68, .24, shirt);
  add('handL', -.43, .91, .02, .2, .18, .2, skin);
  add('handR', .43, .91, .02, .2, .18, .2, skin);
  add('legL', -.17, .48, 0, .24, .68, .28, pants);
  add('legR', .17, .48, 0, .24, .68, .28, pants);
  add('shoeL', -.17, .1, .07, .28, .17, .42, materials.black);
  add('shoeR', .17, .1, .07, .28, .17, .42, materials.black);
  g.userData = {
    parts, civilian, hp: 100, alive: true, stagger: 0, walk: rand(0, 10),
    speed: rand(.35, .8), heading: rand(-3.14, 3.14), panic: 0,
    held: false, thrown: 0, vx: 0, vy: 0, vz: 0
  };
  world.add(g);
  targets.push(g);
  return g;
}
function spawnCivilians(n = 10) {
  for (let i = 0; i < n; i++) {
    if (targets.filter(t => t.userData.alive).length >= MAX_TARGETS) break;
    let x = rand(-16, 16);
    let z = rand(-8, 10);
    if (Math.hypot(x - player.pos.x, z - player.pos.z) < 4.5) {
      x += 7;
      z -= 4;
    }
    makeVoxelPerson(x, z, true);
  }
}

// ---------- Aiming and feedback ----------
const raycaster = new THREE.Raycaster();
raycaster.far = 90;
function aimRay(spread = 0) {
  const origin = camera.getWorldPosition(new THREE.Vector3());
  const dir = camera.getWorldDirection(new THREE.Vector3());
  if (spread) {
    dir.x += rand(-spread, spread);
    dir.y += rand(-spread, spread);
    dir.z += rand(-spread, spread);
    dir.normalize();
  }
  raycaster.set(origin, dir);
  raycaster.far = 90;
  return { origin, dir, ray: raycaster };
}
function aimHits(spread = 0) {
  const aim = aimRay(spread);
  aim.hits = raycaster.intersectObjects([...targets, ...decor], true);
  return aim;
}
function showToast(msg) {
  const t = document.querySelector('#toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => t.classList.remove('show'), 1700);
}
function hitmark() {
  const h = document.querySelector('#hitmark');
  h.classList.remove('show');
  void h.offsetWidth;
  h.classList.add('show');
}
