function bloodPool(pos, size = 1) {
  const geo = new THREE.CircleGeometry(rand(.32, .82) * size, 10);
  const material = new THREE.MeshBasicMaterial({ color: '#5e1016', transparent: true, opacity: .72, depthWrite: false });
  const m = new THREE.Mesh(geo, material);
  m.rotation.x = -Math.PI / 2;
  m.position.set(pos.x + rand(-.5, .5), .012, pos.z + rand(-.5, .5));
  scene.add(m);
  decals.push({ mesh: m, life: 180 });
  if (decals.length > MAX_DECALS) {
    const old = decals.shift();
    scene.remove(old.mesh);
    old.mesh.geometry.dispose();
    old.mesh.material.dispose();
  }
}
function makeShard(part, dir, force = 1) {
  const clone = new THREE.Mesh(part.geometry, part.material);
  clone.position.copy(part.getWorldPosition(new THREE.Vector3()));
  clone.quaternion.copy(part.getWorldQuaternion(new THREE.Quaternion()));
  clone.scale.copy(part.getWorldScale(new THREE.Vector3()));
  clone.castShadow = true;
  scene.add(clone);
  debris.push({
    mesh: clone,
    vel: new THREE.Vector3(rand(-2, 2), rand(1, 5), rand(-2, 2)).add(dir.clone().multiplyScalar(force * rand(.6, 2))),
    spin: new THREE.Vector3(rand(-7, 7), rand(-7, 7), rand(-7, 7)),
    life: 42
  });
  return clone;
}
function makeChunk(pos, color, size, dir, force = 1) {
  const m = new THREE.Mesh(boxGeo, cachedMat(color, .85));
  m.scale.set(size, size * rand(.6, 1.4), size * rand(.6, 1.2));
  m.position.copy(pos).add(new THREE.Vector3(rand(-.6, .6), rand(.2, 1.8), rand(-.6, .6)));
  m.rotation.set(rand(0, 6), rand(0, 6), rand(0, 6));
  m.castShadow = true;
  scene.add(m);
  debris.push({
    mesh: m,
    vel: new THREE.Vector3(rand(-3.5, 3.5), rand(1, 6), rand(-3.5, 3.5)).add(dir.clone().multiplyScalar(force * rand(.3, 1.4))),
    spin: new THREE.Vector3(rand(-8, 8), rand(-8, 8), rand(-8, 8)),
    life: 34
  });
}
function addTracer(start, end) {
  const geo = new THREE.BufferGeometry().setFromPoints([start, end]);
  const material = new THREE.LineBasicMaterial({ color: '#ffe7a8', transparent: true, opacity: .62 });
  const line = new THREE.Line(geo, material);
  scene.add(line);
  setTimeout(() => {
    scene.remove(line);
    geo.dispose();
    material.dispose();
  }, 55);
}

// ---------- Damage, gore, and destruction ----------
function alertNearby(center, radius = 14) {
  for (const t of targets) {
    if (!t.userData.alive || t.position.distanceTo(center) > radius) continue;
    t.userData.panic = Math.max(t.userData.panic, 4.2);
    t.userData.heading = Math.atan2(t.position.x - center.x, t.position.z - center.z);
    t.userData.speed = 3;
  }
  if (state.screamCooldown <= 0) {
    state.screamCooldown = .9;
    sfx('scream');
  }
}
function breakPerson(person, force = 1, dir = null) {
  const d = person.userData;
  if (!d.alive) return;
  d.alive = false;
  d.held = false;
  d.thrown = 0;
  const direction = dir ? dir.clone() : camera.getWorldDirection(new THREE.Vector3());
  for (const p of d.parts) {
    p.visible = false;
    makeShard(p, direction, force);
  }
  const chest = person.position.clone().add(new THREE.Vector3(0, 1.15, 0));
  bloodBurst(chest, 36, 1.35);
  for (let i = 0; i < 3; i++) bloodPool(person.position, rand(.8, 1.4));
  for (let i = 0; i < 4; i++) {
    const m = new THREE.Mesh(boxGeo, i % 2 ? organMat : bloodBright);
    m.scale.set(rand(.12, .25), rand(.1, .2), rand(.12, .22));
    m.position.copy(chest).add(new THREE.Vector3(rand(-.3, .3), rand(-.2, .3), rand(-.3, .3)));
    m.castShadow = true;
    scene.add(m);
    debris.push({
      mesh: m,
      vel: new THREE.Vector3(rand(-2, 2), rand(1, 5), rand(-2, 2)).add(direction.clone().multiplyScalar(force * rand(.5, 1.6))),
      spin: new THREE.Vector3(rand(-8, 8), rand(-8, 8), rand(-8, 8)),
      life: 40
    });
  }
  alertNearby(person.position, 16);
  sfx('death');
  showToast(d.civilian ? 'SUBJECT DOWN — TEST EVENT' : 'TARGET DISABLED');
  setTimeout(() => {
    if (person.parent) person.parent.remove(person);
    targets = targets.filter(t => t !== person);
  }, 45000);
}
function damageTarget(hit, force = 1, damage = null, dir = null) {
  let obj = hit.object;
  while (obj && !obj.userData?.parts) obj = obj.parent;
  if (!obj) return false;
  const d = obj.userData;
  if (!d.alive) return false;
  const amount = damage ?? (weaponDefs[state.weapon]?.damage || 30);
  d.hp -= amount;
  d.stagger = Math.max(d.stagger, .7);
  d.panic = 3.5;
  const direction = dir ? dir.clone() : camera.getWorldDirection(new THREE.Vector3());
  obj.position.addScaledVector(direction, .1 * force);
  bloodBurst(hit.point, 8, .7);
  hitmark();
  sfx('hit');
  alertNearby(obj.position, 12);
  if (d.hp <= 0) breakPerson(obj, force, direction);
  return true;
}
function topDecor(obj) {
  let o = obj;
  while (o && o.parent !== world) o = o.parent;
  return o && decor.includes(o) ? o : null;
}
function destroyProp(root, dir = null) {
  if (!root || !decor.includes(root)) return;
  const pos = root.position.clone();
  const kind = root.userData.kind;
  const colors = kind === 'tree' ? ['#805f3d', '#477d55', '#67945a'] : kind === 'house' ? ['#adb8a4', '#475b4b', '#604a37'] : kind === 'vehicle' ? ['#477d55', '#67945a', '#57615e'] : ['#477d55', '#67945a'];
  const count = kind === 'house' ? 18 : kind === 'tree' ? 12 : 8;
  const direction = dir ? dir.clone() : new THREE.Vector3(rand(-1, 1), 0, rand(-1, 1));
  for (let i = 0; i < count; i++) makeChunk(pos, colors[i % colors.length], rand(.18, .55), direction, 1.4);
  spark(pos.clone().add(new THREE.Vector3(0, 1, 0)), '#c7bf9c', 12, 1);
  world.remove(root);
  decor = decor.filter(d => d !== root);
  vehicles = vehicles.filter(v => v !== root);
  if (kind === 'house' || kind === 'vehicle') showToast(kind === 'house' ? 'STRUCTURE COLLAPSED' : 'VEHICLE WRECKED');
  sfx(kind === 'house' || kind === 'vehicle' ? 'crash' : 'wood');
}
function damageProp(hit, dir = null) {
  const root = topDecor(hit.object);
  if (!root) return false;
  root.userData.hp = (root.userData.hp ?? 4) - 1;
  spark(hit.point, root.userData.kind === 'tree' ? '#a9c77a' : '#c7bfa2', 5, .5);
  if (root.userData.hp <= 0) destroyProp(root, dir);
  return true;
}
function impact(damage, spread = 0, force = 1) {
  const { origin, dir, hits } = aimHits(spread);
  if (hits.length) {
    const h = hits[0];
    const hitPerson = damageTarget(h, force, damage, dir);
    if (!hitPerson) damageProp(h, dir);
    addTracer(origin, h.point);
    return true;
  }
  const end = origin.clone().addScaledVector(dir, 36);
  spark(end, '#c7c69a', 4, .3);
  addTracer(origin, end);
  return false;
}
function burst(center, radius = 8, power = 12) {
  spark(center, '#ffb35b', 38, 1.8);
  const flash = new THREE.PointLight('#ff9d47', 22, 18);
  flash.position.copy(center);
  scene.add(flash);
  setTimeout(() => scene.remove(flash), 260);
  sfx('explosion');
  for (const t of targets) {
    if (!t.userData.alive) continue;
    const dist = t.position.distanceTo(center);
    if (dist >= radius) continue;
    const amount = Math.round((1 - dist / radius) * 150);
    t.userData.hp -= amount;
    t.userData.stagger = 2;
    t.userData.panic = 6;
    t.position.add(t.position.clone().sub(center).normalize().multiplyScalar(.8));
    bloodBurst(t.position.clone().add(new THREE.Vector3(0, 1.1, 0)), 10, .9);
    if (t.userData.hp <= 0) breakPerson(t, power);
  }
  for (const item of debris) {
    const dist = item.mesh.position.distanceTo(center);
    if (dist < radius) item.vel.add(item.mesh.position.clone().sub(center).normalize().multiplyScalar(power * (1 - dist / radius)));
  }
  for (const root of [...decor]) {
    if (root.position.distanceTo(center) < radius * .8) destroyProp(root, root.position.clone().sub(center));
  }
  const playerDist = player.pos.distanceTo(center);
  if (playerDist < radius) hurtPlayer((1 - playerDist / radius) * 58);
}

// ---------- Persistent fire ----------
function addFire(point) {
  if (fires.length >= 8) {
    const old = fires.shift();
    scene.remove(old.group);
  }
  const group = new THREE.Group();
  group.position.copy(point);
  group.position.y = Math.max(.05, Math.min(point.y, .35));
  const light = new THREE.PointLight('#ff7a2f', 9, 11);
  light.position.set(0, 1.1, 0);
  group.add(light);
  const flames = [];
  for (let i = 0; i < 6; i++) {
    const m = new THREE.Mesh(new THREE.IcosahedronGeometry(rand(.16, .34), 0), new THREE.MeshBasicMaterial({
      color: i % 2 ? '#ffb23d' : '#ff5a1f', transparent: true, opacity: .82
    }));
    m.position.set(rand(-.38, .38), rand(.18, .95), rand(-.38, .38));
    group.add(m);
    flames.push(m);
  }
  scene.add(group);
  fires.push({ group, light, flames, life: 22, tick: 0, phase: rand(0, 6) });
  sfx('fire');
}
function lightningBolt(start, end) {
  const pts = [];
  for (let i = 0; i <= 9; i++) {
    const p = start.clone().lerp(end, i / 9);
    if (i > 0 && i < 9) p.add(new THREE.Vector3(rand(-.45, .45), rand(-.45, .45), rand(-.45, .45)));
    pts.push(p);
  }
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const material = new THREE.LineBasicMaterial({ color: '#c3a5ff', transparent: true, opacity: .95 });
  const line = new THREE.Line(geo, material);
  scene.add(line);
  setTimeout(() => {
    scene.remove(line);
    geo.dispose();
    material.dispose();
  }, 150);
}

// ---------- God tools ----------
function doGod(action) {
  const aim = aimHits(0);
  const point = aim.hits[0]?.point || aim.origin.clone().addScaledVector(aim.dir, 9);
  if (action === 'grab') {
    state.grabMode = !state.grabMode;
    if (!state.grabMode) dropHeld();
    showToast(state.grabMode ? 'GRAB TOOL ARMED — CLICK OBJECT' : 'GRAB TOOL OFF');
    return;
  }
  if (action === 'push') {
    for (const t of targets) {
      if (t.position.distanceTo(point) < 10) {
        t.position.add(t.position.clone().sub(point).normalize().multiplyScalar(1.3));
        t.userData.stagger = 1.5;
        t.userData.panic = 4;
      }
    }
    for (const item of debris) {
      if (item.mesh.position.distanceTo(point) < 10) item.vel.add(item.mesh.position.clone().sub(point).normalize().multiplyScalar(14));
    }
    for (const root of [...decor]) {
      if (root.position.distanceTo(point) < 5) destroyProp(root, root.position.clone().sub(point));
    }
    spark(point, '#b9d1c5', 22, 1);
    sfx('push');
    showToast('FORCE PUSH');
    return;
  }
  if (action === 'lightning') {
    lightningBolt(aim.origin, point);
    for (const t of targets) {
      if (t.position.distanceTo(point) < 8) {
        t.userData.hp -= 90;
        t.userData.stagger = 2;
        t.userData.panic = 5;
        bloodBurst(t.position.clone().add(new THREE.Vector3(0, 1.1, 0)), 12, .9);
        if (t.userData.hp <= 0) breakPerson(t, 2);
      }
    }
    spark(point, '#b693ff', 22, 1);
    sfx('thunder');
    showToast('LIGHTNING STRIKE');
    return;
  }
  if (action === 'blast') {
    burst(point, 9, 15);
    showToast('KINETIC EVENT');
    return;
  }
  if (action === 'fire') {
    addFire(point);
    showToast('FIRE DEPLOYED');
    return;
  }
  if (action === 'slow') {
    state.slow = !state.slow;
    showToast(state.slow ? 'TIME DILATION ON' : 'TIME NORMAL');
    return;
  }
  if (action === 'spawn') {
    if (targets.filter(t => t.userData.alive).length >= MAX_TARGETS) {
      showToast('FIELD AT CAPACITY');
      return;
    }
    makeVoxelPerson(point.x + rand(-2, 2), point.z + rand(-2, 2), true);
    showToast('SUBJECT ENTERED FIELD');
    return;
  }
  if (action === 'clean') {
    cleanup();
    return;
  }
  if (action === 'map') {
    changeMap();
    return;
  }
  if (action === 'eyes') {
    state.eyes = !state.eyes;
    showToast(state.eyes ? 'LASER EYES ONLINE' : 'LASER EYES OFFLINE');
  }
}

// ---------- Grab and throw ----------
function dropHeld() {
  if (!state.held) return;
  if (state.held.kind === 'target') state.held.obj.userData.held = false;
  if (state.held.kind === 'prop') state.held.obj.userData.held = false;
  state.held = null;
}
function beginGrabOrThrow() {
  if (!state.grabMode) return false;
  if (state.held) {
    throwHeld();
    return true;
  }
  const aim = aimHits(0, debris.map(d => d.mesh));
  if (!aim.hits.length) {
    showToast('NOTHING TO GRAB');
    return true;
  }
  const hit = aim.hits[0];
  let target = hit.object;
  while (target && !target.userData?.parts) target = target.parent;
  const item = debris.find(d => d.mesh === hit.object);
  const prop = topDecor(hit.object);
  if (target) {
    state.held = { kind: 'target', obj: target };
    target.userData.held = true;
    target.userData.thrown = 0;
  } else if (item) {
    state.held = { kind: 'debris', item };
  } else if (prop) {
    state.held = { kind: 'prop', obj: prop };
    prop.userData.held = true;
  } else {
    showToast('TOO SOLID TO GRAB');
    return true;
  }
  sfx('grab');
  showToast('GRABBED — CLICK TO THROW');
  return true;
}
function throwHeld() {
  if (!state.held) return;
  const { dir } = aimRay();
  if (state.held.kind === 'target') {
    const t = state.held.obj;
    const d = t.userData;
    d.held = false;
    d.thrown = 2.4;
    d.vx = dir.x * 22;
    d.vy = dir.y * 22 + 4.5;
    d.vz = dir.z * 22;
    d.panic = 6;
    d.stagger = 1;
  } else if (state.held.kind === 'debris') {
    const item = state.held.item;
    item.vel.copy(dir).multiplyScalar(24);
    item.vel.y += 4;
  } else if (state.held.kind === 'prop') {
    const obj = state.held.obj;
    obj.userData.held = false;
    thrownProps.push({
      obj,
      vel: dir.clone().multiplyScalar(18).add(new THREE.Vector3(0, 4, 0)),
      spin: new THREE.Vector3(rand(-3, 3), rand(-3, 3), rand(-3, 3)),
      life: 2.4
    });
  }
  state.held = null;
  sfx('throw');
  showToast('THROWN');
}
function updateHeld(dt) {
  if (!state.held) return;
  const { origin, dir } = aimRay();
  const hold = origin.clone().addScaledVector(dir, 4.2);
  if (state.held.kind === 'target') {
    hold.y -= 1.1;
    const obj = state.held.obj;
    obj.position.lerp(hold, Math.min(1, dt * 9));
    obj.rotation.y += dt * 2;
  } else if (state.held.kind === 'debris') {
    const mesh = state.held.item.mesh;
    mesh.position.lerp(hold, Math.min(1, dt * 12));
    mesh.rotation.y += dt * 3;
  } else if (state.held.kind === 'prop') {
    hold.y -= 1.3;
    const obj = state.held.obj;
    obj.position.lerp(hold, Math.min(1, dt * 6));
    obj.rotation.y += dt * 1.5;
  }
}
function updateThrownProps(dt) {
  for (let i = thrownProps.length - 1; i >= 0; i--) {
    const p = thrownProps[i];
    p.life -= dt;
    p.vel.y -= 20 * dt;
    p.obj.position.addScaledVector(p.vel, dt);
    p.obj.rotation.x += p.spin.x * dt;
    p.obj.rotation.y += p.spin.y * dt;
    p.obj.rotation.z += p.spin.z * dt;
    if (p.obj.position.y <= 0 || p.life <= 0) {
      p.obj.position.y = Math.max(0, p.obj.position.y);
      destroyProp(p.obj, p.vel.clone().setY(0));
      thrownProps.splice(i, 1);
    }
  }
}

// ---------- Weapons ----------
const weaponDefs = {
  GUARD: { max: Infinity, damage: 18, cooldown: .38, range: 2.7, auto: false, sound: 'guard' },
  RIFLE: { max: 30, damage: 34, cooldown: .14, auto: true, sound: 'rifle', spread: .003, force: 1 },
  DEAGLE: { max: 8, damage: 60, cooldown: .32, auto: false, sound: 'deagle', spread: .006, force: 1.5 },
  SHOTGUN: { max: 6, damage: 16, cooldown: .8, auto: false, sound: 'shotgun', pellets: 7, spread: .075, force: 1.1 },
  GRENADE: { max: Infinity, cooldown: .8, auto: false },
  FLAME: { max: 100, damage: 14, cooldown: .09, auto: true, sound: 'flame', spread: .04 },
  KAT: { max: Infinity, damage: 50, cooldown: .55, auto: false, range: 3.2, sound: 'katana' }
};
const weaponOrder = ['GUARD', 'RIFLE', 'DEAGLE', 'GRENADE', 'FLAME', 'KAT', 'SHOTGUN'];

function updateAmmoHud() {
  document.querySelector('#ammoName').textContent = state.reloading ? 'RELOADING' : state.weapon;
  document.querySelector('#ammoText').textContent = Number.isFinite(state.maxAmmo) ? state.ammo + ' / ' + state.maxAmmo : '∞';
}
function updateWeaponButtons() {
  document.querySelectorAll('.weapon').forEach(b => b.classList.toggle('selected', b.dataset.weapon === state.weapon));
}
function selectWeapon(name, silent = false) {
  const def = weaponDefs[name];
  if (!def) return;
  state.weapon = name;
  state.maxAmmo = def.max;
  state.reloading = false;
  state.reloadToken++;
  if (Number.isFinite(def.max)) {
    state.ammo = mags[name] ?? def.max;
    mags[name] = state.ammo;
  } else {
    state.ammo = Infinity;
  }
  buildGun();
  updateAmmoHud();
  updateWeaponButtons();
  if (!silent) {
    showToast(name + ' EQUIPPED');
    sfx('switch');
  }
}
function consumeAmmo() {
  if (!Number.isFinite(state.maxAmmo)) return true;
  if (state.ammo <= 0) {
    showToast('MAGAZINE EMPTY — RELOAD');
    sfx('empty');
    return false;
  }
  state.ammo--;
  mags[state.weapon] = state.ammo;
  updateAmmoHud();
  return true;
}
function muzzleFlash(color = '#ffd36b', count = 4) {
  const origin = state.third ? camera.getWorldPosition(new THREE.Vector3()) : gun.getWorldPosition(new THREE.Vector3());
  spark(origin, color, count, .35);
  const flash = new THREE.PointLight(color, 4, 5);
  flash.position.copy(origin);
  scene.add(flash);
  setTimeout(() => scene.remove(flash), 70);
}
function reload() {
  const def = weaponDefs[state.weapon];
  if (!def || !Number.isFinite(def.max) || state.reloading || state.ammo >= def.max) return;
  state.reloading = true;
  state.reloadStart = performance.now();
  state.reloadTime = state.weapon === 'SHOTGUN' ? 1300 : 900;
  const token = ++state.reloadToken;
  updateAmmoHud();
  sfx('reload');
  showToast('RELOADING…');
  setTimeout(() => {
    if (token !== state.reloadToken) return;
    state.reloading = false;
    state.ammo = state.maxAmmo;
    mags[state.weapon] = state.ammo;
    updateAmmoHud();
    sfx('reloadEnd');
    showToast('MAGAZINE READY');
  }, state.reloadTime);
}
function fire() {
  if (!state.playing || state.fireCooldown > 0 || state.reloading) return;
  const def = weaponDefs[state.weapon];
  if (!def) return;
  if (state.weapon === 'GUARD') {
    state.fireCooldown = def.cooldown;
    const { origin, dir, hits } = aimHits(0);
    if (hits.length && hits[0].distance < def.range) {
      if (!damageTarget(hits[0], .45, def.damage, dir)) damageProp(hits[0], dir);
    }
    spark(origin.clone().addScaledVector(dir, 1.3), '#f3d9ad', 3, .25);
    sfx('guard');
    state.recoil = .035;
    return;
  }
  if (state.weapon === 'GRENADE') {
    state.fireCooldown = def.cooldown;
    const { origin, dir } = aimRay();
    const orb = new THREE.Mesh(new THREE.IcosahedronGeometry(.2, 1), cachedMat('#d7aa4a'));
    orb.position.copy(origin).addScaledVector(dir, .8);
    orb.castShadow = true;
    scene.add(orb);
    debris.push({
      mesh: orb,
      vel: dir.clone().multiplyScalar(15).add(new THREE.Vector3(0, 4, 0)),
      spin: new THREE.Vector3(2, 4, 1),
      life: 2.1,
      grenade: true
    });
    sfx('throw');
    state.recoil = .03;
    return;
  }
  if (state.weapon === 'KAT') {
    state.fireCooldown = def.cooldown;
    const { origin, dir, hits } = aimHits(0);
    if (hits.length && hits[0].distance < def.range) {
      if (!damageTarget(hits[0], 2, def.damage, dir)) damageProp(hits[0], dir);
    }
    spark(origin.clone().addScaledVector(dir, 2), '#fff0bb', 6, .4);
    sfx('katana');
    state.recoil = .05;
    return;
  }
  if (state.weapon === 'SHOTGUN') {
    if (!consumeAmmo()) return;
    state.fireCooldown = def.cooldown;
    for (let i = 0; i < def.pellets; i++) {
      const { origin, dir, hits } = aimHits(def.spread);
      if (hits.length) {
        const h = hits[0];
        if (!damageTarget(h, 1, def.damage, dir)) damageProp(h, dir);
        addTracer(origin, h.point);
      } else {
        addTracer(origin, origin.clone().addScaledVector(dir, 30));
      }
    }
    muzzleFlash('#ffd36b', 8);
    sfx('shotgun');
    state.recoil = .11;
    return;
  }
  if (state.weapon === 'FLAME') {
    if (!consumeAmmo()) return;
    state.fireCooldown = def.cooldown;
    const { origin, dir, hits } = aimHits(def.spread);
    for (let i = 0; i < 5; i++) {
      const p = origin.clone().addScaledVector(dir, rand(.5, 4));
      p.x += rand(-.22, .22);
      p.y += rand(-.18, .18);
      spark(p, i % 2 ? '#ff7134' : '#ffc247', 2, .5);
    }
    if (hits.length && hits[0].distance < 12) {
      if (!damageTarget(hits[0], .35, def.damage, dir)) damageProp(hits[0], dir);
    }
    sfx('flame');
    state.recoil = .02;
    return;
  }
  if (!consumeAmmo()) return;
  state.fireCooldown = def.cooldown;
  impact(def.damage, def.spread || 0, def.force || 1);
  muzzleFlash();
  sfx(def.sound || 'rifle');
  state.recoil = state.weapon === 'DEAGLE' ? .085 : .065;
}
function updateGun(dt) {
  state.recoil = Math.max(0, state.recoil - dt * 1.1);
  let dip = 0;
  if (state.reloading) {
    const p = clamp((performance.now() - state.reloadStart) / state.reloadTime, 0, 1);
    dip = Math.sin(p * Math.PI) * .2;
  }
  gun.position.set(GUN_BASE.x, GUN_BASE.y - dip, GUN_BASE.z + state.recoil);
  gun.rotation.x = state.recoil * 2.5;
  gun.visible = !state.third;
}

// ---------- Player and camera ----------
const keys = {};
function updateVitals(dt) {
  if (player.hurtTimer > 0) player.hurtTimer -= dt;
  else player.hp = clamp(player.hp + dt * 4, 0, 100);
  player.sta = clamp(player.sta + dt * 13, 0, 100);
  document.querySelector('#hpFill').style.width = player.hp + '%';
  document.querySelector('#hpText').textContent = Math.round(player.hp);
  document.querySelector('#staFill').style.width = player.sta + '%';
  document.querySelector('#staText').textContent = Math.round(player.sta);
}
function hurtPlayer(amount) {
  if (!state.playing) return;
  player.hp = clamp(player.hp - amount, 0, 100);
  player.hurtTimer = 3;
  const el = document.querySelector('#hurt');
  el.style.opacity = Math.min(.78, .18 + amount / 65);
  clearTimeout(hurtPlayer.timer);
  hurtPlayer.timer = setTimeout(() => { el.style.opacity = 0; }, 150);
  sfx('hurt');
  if (player.hp <= 0) {
    player.hp = 100;
    player.pos.set(0, 0, 15);
    player.vel.set(0, 0, 0);
    player.hurtTimer = 0;
    showToast('SUBJECT RECONSTRUCTED AT SPAWN');
    sfx('respawn');
  }
  updateVitals(0);
}
function toggleCamera() {
  state.third = !state.third;
  camera.position.set(0, state.third ? 2.45 : 0, state.third ? 5.4 : 0);
  camera.rotation.set(0, 0, 0);
  gun.visible = !state.third;
  avatar.visible = state.third;
  document.querySelector('#cameraBtn').classList.toggle('active', state.third);
  showToast(state.third ? 'THIRD PERSON' : 'FIRST PERSON');
}
function toggleLaser() {
  state.laser = !state.laser;
  document.querySelector('#laserBtn').textContent = state.laser ? 'LASER ON' : 'LASER OFF';
  document.querySelector('#laserBtn').classList.toggle('active', state.laser);
  showToast(state.laser ? 'LASER SIGHT ON' : 'LASER SIGHT OFF');
}
function updatePlayer(dt) {
  const fwd = new THREE.Vector3(-Math.sin(player.yaw), 0, -Math.cos(player.yaw));
  const right = new THREE.Vector3(Math.cos(player.yaw), 0, -Math.sin(player.yaw));
  const x = (keys.KeyD ? 1 : 0) - (keys.KeyA ? 1 : 0) + mobile.x;
  const z = (keys.KeyS ? 1 : 0) - (keys.KeyW ? 1 : 0) + mobile.y;
  const move = fwd.multiplyScalar(-z).add(right.multiplyScalar(x));
  if (move.lengthSq() > 1) move.normalize();
  const speed = keys.ShiftLeft ? 8 : 5.5;
  player.vel.x += (move.x * speed - player.vel.x) * Math.min(1, dt * 9);
  player.vel.z += (move.z * speed - player.vel.z) * Math.min(1, dt * 9);
  if (keys.Space && player.ground) {
    player.vel.y = 7;
    player.ground = false;
    player.sta = Math.max(0, player.sta - 12);
  }
  player.vel.y -= 20 * dt;
  player.pos.addScaledVector(player.vel, dt);
  if (player.pos.y < 0) {
    player.pos.y = 0;
    player.vel.y = 0;
    player.ground = true;
  }
  player.pos.x = clamp(player.pos.x, -105, 105);
  player.pos.z = clamp(player.pos.z, -105, 105);
  state.viewBob += dt * (move.lengthSq() ? 12 : 3);
  yawObj.position.set(player.pos.x, player.pos.y + (state.third ? 0 : 1.62), player.pos.z);
  yawObj.rotation.y = player.yaw;
  pitchObj.rotation.x = player.pitch;
  avatar.position.copy(player.pos);
  avatar.rotation.y = player.yaw;
  avatar.visible = state.third;
  updateVitals(dt);
}
function updateLaser() {
  laserLine.visible = state.laser || state.eyes;
  laserDot.style.display = state.laser ? 'block' : 'none';
  laserMaterial.color.set(state.eyes ? '#ff2b2b' : '#ff263c');
  if (!state.laser && !state.eyes) return;
  const { origin, dir, hits } = aimHits(0);
  const end = hits.length ? hits[0].point : origin.clone().addScaledVector(dir, 80);
  laserGeometry.setFromPoints([origin, end]);
  if (state.laser) {
    const screen = end.clone().project(camera);
    laserDot.style.left = ((screen.x * .5 + .5) * innerWidth) + 'px';
    laserDot.style.top = ((-screen.y * .5 + .5) * innerHeight) + 'px';
  }
  if (state.eyes && hits.length && Math.random() < .06) {
    const h = hits[0];
    if (!damageTarget(h, .5, 22, dir)) damageProp(h, dir);
  }
}

// ---------- World update ----------
function updateWorld(dt) {
  state.screamCooldown = Math.max(0, state.screamCooldown - dt);
  for (const t of targets) {
    const d = t.userData;
    if (!d.alive || d.held) continue;
    if (d.thrown > 0) {
      d.thrown -= dt;
      t.position.x += d.vx * dt;
      t.position.y += d.vy * dt;
      t.position.z += d.vz * dt;
      d.vy -= 24 * dt;
      if (t.position.y <= 0 || d.thrown <= 0) {
        t.position.y = Math.max(0, t.position.y);
        breakPerson(t, 2.5, new THREE.Vector3(d.vx, 0, d.vz));
      }
      continue;
    }
    d.walk += dt * (d.panic > 0 ? 2.3 : 1);
    d.stagger = Math.max(0, d.stagger - dt);
    const dist = t.position.distanceTo(player.pos);
    if (d.panic > 0) {
      d.panic -= dt;
      d.heading = Math.atan2(t.position.x - player.pos.x, t.position.z - player.pos.z) + Math.PI;
      d.speed = 2.8;
    } else {
      d.speed = .55;
    }
    const spd = d.stagger > 0 ? d.speed * .15 : d.speed;
    t.position.x += Math.sin(d.heading) * spd * dt;
    t.position.z += Math.cos(d.heading) * spd * dt;
    if (d.panic <= 0 && Math.random() < dt * .12) d.heading += rand(-1, 1);
    if (Math.abs(t.position.x) > 50 || Math.abs(t.position.z) > 50) d.heading = Math.atan2(-t.position.x, -t.position.z);
    t.position.x = clamp(t.position.x, -52, 52);
    t.position.z = clamp(t.position.z, -52, 52);
    t.position.y = Math.sin(d.walk * 6) * .035;
    for (const p of d.parts) {
      if (p.userData.part === 'armL') p.rotation.x = Math.sin(d.walk * 5) * .11;
      if (p.userData.part === 'armR') p.rotation.x = -Math.sin(d.walk * 5) * .11;
      if (p.userData.part === 'legL') p.rotation.x = Math.sin(d.walk * 5) * .08;
      if (p.userData.part === 'legR') p.rotation.x = -Math.sin(d.walk * 5) * .08;
    }
    if (dist < 1.6 && d.panic <= 0) d.heading += dt * 1.5;
  }
  for (let i = debris.length - 1; i >= 0; i--) {
    const o = debris[i];
    o.life -= dt;
    if (o.grenade && o.life <= 0) {
      burst(o.mesh.position, 9, 13);
      scene.remove(o.mesh);
      debris.splice(i, 1);
      continue;
    }
    if (o.life <= 0) {
      scene.remove(o.mesh);
      debris.splice(i, 1);
      continue;
    }
    o.vel.y -= 14 * dt;
    o.mesh.position.addScaledVector(o.vel, dt);
    o.mesh.rotation.x += o.spin.x * dt;
    o.mesh.rotation.y += o.spin.y * dt;
    if (o.mesh.position.y < .12) {
      o.mesh.position.y = .12;
      if (o.vel.y < -1) o.vel.y *= -.38;
      else o.vel.y = 0;
      o.vel.x *= .82;
      o.vel.z *= .82;
    }
  }
  for (let i = effects.length - 1; i >= 0; i--) {
    const e = effects[i];
    e.life -= dt;
    e.vel.y -= e.gravity * dt;
    e.mesh.position.addScaledVector(e.vel, dt);
    e.mesh.scale.multiplyScalar(Math.max(.01, 1 - dt * 1.8));
    if (e.life <= 0) {
      scene.remove(e.mesh);
      effects.splice(i, 1);
    }
  }
  for (let i = decals.length - 1; i >= 0; i--) {
    const d = decals[i];
    d.life -= dt;
    if (d.life <= 0) {
      scene.remove(d.mesh);
      d.mesh.geometry.dispose();
      d.mesh.material.dispose();
      decals.splice(i, 1);
    }
  }
  updateThrownProps(dt);
}
function updateFires(dt) {
  const now = performance.now() * .001;
  for (let i = fires.length - 1; i >= 0; i--) {
    const f = fires[i];
    f.life -= dt;
    f.tick -= dt;
    f.flames.forEach((m, j) => {
      m.position.y = .35 + Math.abs(Math.sin(now * 3 + f.phase + j)) * .7;
      m.scale.setScalar(.85 + Math.sin(now * 8 + j) * .16);
    });
    f.light.intensity = 8 + Math.sin(now * 9 + f.phase) * 2.2;
    if (f.tick <= 0) {
      f.tick = .38;
      for (const t of targets) {
        if (!t.userData.alive || t.position.distanceTo(f.group.position) > 3.2) continue;
        t.userData.hp -= 13;
        t.userData.stagger = .5;
        t.userData.panic = 3;
        if (t.userData.hp <= 0) breakPerson(t, 1.2);
      }
      if (player.pos.distanceTo(f.group.position) < 2.6) hurtPlayer(9);
      if (Math.random() < .4) spark(f.group.position.clone().add(new THREE.Vector3(rand(-.5, .5), rand(.3, 1), rand(-.5, .5))), '#ffb23d', 2, .3);
    }
    if (f.life <= 0) {
      scene.remove(f.group);
      fires.splice(i, 1);
    }
  }
}

// ---------- Scene lifecycle ----------
function cleanup() {
  for (const t of targets) if (t.parent) t.parent.remove(t);
  for (const d of debris) scene.remove(d.mesh);
  for (const e of effects) scene.remove(e.mesh);
  for (const d of decals) {
    scene.remove(d.mesh);
    d.mesh.geometry.dispose();
    d.mesh.material.dispose();
  }
  for (const f of fires) scene.remove(f.group);
  for (const p of thrownProps) if (p.obj.parent) world.remove(p.obj);
  targets = [];
  debris = [];
  effects = [];
  decals = [];
  fires = [];
  thrownProps = [];
  state.held = null;
  state.grabMode = false;
  showToast('FIELD CLEANED');
}
function changeMap() {
  cleanup();
  buildMap((mapIndex + 1) % 4);
  spawnCivilians(10);
  player.pos.set(0, 0, 15);
  player.vel.set(0, 0, 0);
  player.yaw = 0;
  player.pitch = 0;
  player.hp = 100;
  player.hurtTimer = 0;
  updateVitals(0);
  showToast('MAP LOADED — ' + document.querySelector('#mapName').textContent);
}

// ---------- UI and controls ----------
function buildWeaponUI() {
  const bottom = document.querySelector('#bottom');
  bottom.innerHTML = '';
  weaponOrder.forEach((name, i) => {
    const b = document.createElement('button');
    b.className = 'weapon';
    b.dataset.weapon = name;
    b.innerHTML = `<span class="num">${i + 1}</span><span class="name">${name}</span>`;
    b.onclick = () => { ensureAudio(); selectWeapon(name); };
    bottom.appendChild(b);
  });
  updateWeaponButtons();
}
function startGame() {
  ensureAudio();
  state.playing = true;
  document.querySelector('#start').style.display = 'none';
  document.body.classList.add('playing');
  try { renderer.domElement.requestPointerLock?.(); } catch (e) {}
  showToast('FIELD TEST READY');
}
function toggleMute() {
  state.muted = !state.muted;
  document.querySelector('#soundBtn').textContent = state.muted ? 'SOUND OFF' : 'SOUND ON';
  showToast(state.muted ? 'AUDIO MUTED' : 'AUDIO ON');
}

const laserMaterial = new THREE.LineBasicMaterial({ color: '#ff263c', transparent: true, opacity: .8 });
const laserGeometry = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3(0, 0, -80)]);
const laserLine = new THREE.Line(laserGeometry, laserMaterial);
scene.add(laserLine);
const laserDot = document.querySelector('#laserDot');

let mobile = { x: 0, y: 0 };
let touchLookMoved = false;
let lastTouch = null;
const stick = document.querySelector('#mobile');
const nub = document.querySelector('#stick');
function moveStick(e) {
  const r = stick.getBoundingClientRect();
  const dx = e.clientX - (r.left + r.width / 2);
  const dy = e.clientY - (r.top + r.height / 2);
  const d = Math.hypot(dx, dy);
  const s = Math.min(28, d);
  mobile = { x: dx / (d || 1) * s / 28, y: dy / (d || 1) * s / 28 };
  nub.style.transform = `translate(${mobile.x * 25}px,${mobile.y * 25}px)`;
}
stick.addEventListener('pointerdown', e => {
  stick.setPointerCapture(e.pointerId);
  moveStick(e);
});
stick.addEventListener('pointermove', e => { if (e.buttons) moveStick(e); });
stick.addEventListener('pointerup', () => {
  mobile = { x: 0, y: 0 };
  nub.style.transform = 'translate(0,0)';
});
renderer.domElement.addEventListener('touchstart', e => {
  if (e.touches.length === 1) {
    lastTouch = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    touchLookMoved = false;
  }
}, { passive: true });
renderer.domElement.addEventListener('touchmove', e => {
  if (lastTouch && e.touches.length === 1) {
    const t = e.touches[0];
    const dx = t.clientX - lastTouch.x;
    const dy = t.clientY - lastTouch.y;
    if (Math.abs(dx) + Math.abs(dy) > 3) touchLookMoved = true;
    player.yaw -= dx * .006;
    player.pitch = clamp(player.pitch - dy * .006, -1.2, 1.2);
    lastTouch = { x: t.clientX, y: t.clientY };
  }
}, { passive: true });
renderer.domElement.addEventListener('touchend', () => { lastTouch = null; });

renderer.domElement.addEventListener('pointerdown', e => {
  if (e.pointerType === 'touch' || !state.playing) return;
  if (!state.mouseLocked) {
    try { renderer.domElement.requestPointerLock?.(); } catch (err) {}
    return;
  }
  if (state.grabMode) {
    beginGrabOrThrow();
    return;
  }
  state.fireHeld = true;
  fire();
});
renderer.domElement.addEventListener('pointerup', () => { state.fireHeld = false; });
renderer.domElement.addEventListener('click', e => {
  if (!state.playing) return;
  if (e.pointerType === 'touch') {
    if (touchLookMoved) {
      touchLookMoved = false;
      return;
    }
    if (state.grabMode) beginGrabOrThrow();
    else fire();
    return;
  }
  if (!state.mouseLocked) {
    try { renderer.domElement.requestPointerLock?.(); } catch (err) {}
  }
});
window.addEventListener('pointerup', () => { state.fireHeld = false; });
document.addEventListener('pointerlockchange', () => {
  state.mouseLocked = document.pointerLockElement === renderer.domElement;
});
document.addEventListener('mousemove', e => {
  if (!state.mouseLocked) return;
  player.yaw -= e.movementX * .0022;
  player.pitch = clamp(player.pitch - e.movementY * .0019, -1.25, 1.25);
});
window.addEventListener('keydown', e => {
  keys[e.code] = true;
  if (['Space', 'ArrowUp', 'ArrowDown'].includes(e.code)) e.preventDefault();
  if (!state.playing) return;
  if (e.code === 'KeyV') toggleCamera();
  if (e.code === 'KeyE') toggleLaser();
  if (e.code === 'KeyR') reload();
  if (e.code === 'KeyM') toggleMute();
  if (e.code.startsWith('Digit')) {
    const idx = Number(e.code.slice(5)) - 1;
    if (weaponOrder[idx]) selectWeapon(weaponOrder[idx]);
  }
  if (e.code === 'Escape') document.exitPointerLock?.();
});
window.addEventListener('keyup', e => { keys[e.code] = false; });
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
  renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
});
window.addEventListener('wheel', e => {
  if (!state.playing) return;
  const current = weaponOrder.indexOf(state.weapon);
  const next = (current + (e.deltaY > 0 ? 1 : weaponOrder.length - 1)) % weaponOrder.length;
  selectWeapon(weaponOrder[next]);
}, { passive: true });

document.querySelector('#cameraBtn').onclick = toggleCamera;
document.querySelector('#cleanBtn').onclick = cleanup;
document.querySelector('#reloadBtn').onclick = reload;
document.querySelector('#jumpBtn').onclick = () => {
  if (player.ground) {
    player.vel.y = 7;
    player.ground = false;
    player.sta = Math.max(0, player.sta - 12);
  }
};
document.querySelector('#fireBtn').onpointerdown = e => {
  e.preventDefault();
  ensureAudio();
  state.fireHeld = true;
  fire();
};
document.querySelector('#fireBtn').onpointerup = () => { state.fireHeld = false; };
document.querySelector('#fireBtn').onpointerleave = () => { state.fireHeld = false; };
document.querySelector('#laserBtn').onclick = toggleLaser;
document.querySelector('#godBtn').onclick = () => {
  const p = document.querySelector('#godPanel');
  p.style.display = p.style.display === 'block' ? 'none' : 'block';
};
document.querySelector('#godClose').onclick = () => { document.querySelector('#godPanel').style.display = 'none'; };
document.querySelectorAll('[data-god]').forEach(b => b.onclick = () => doGod(b.dataset.god));
document.querySelector('#soundBtn').onclick = toggleMute;
document.querySelector('#playBtn').onclick = startGame;

// ---------- Boot ----------
buildMap(0);
spawnCivilians(10);
buildWeaponUI();
selectWeapon('RIFLE', true);
updateVitals(0);

window.MemeticBox = {
  state, player, targets, fire, doGod, selectWeapon, reload, cleanup, changeMap,
  addFire, spawnCivilians, get fires() { return fires; }
};

function animate() {
  requestAnimationFrame(animate);
  const raw = clock.getDelta();
  const dt = Math.min(.04, raw) * (state.slow ? .22 : 1);
  state.fireCooldown = Math.max(0, state.fireCooldown - dt);
  if (state.fireHeld && state.playing && weaponDefs[state.weapon]?.auto) fire();
  updatePlayer(dt);
  updateHeld(dt);
  updateWorld(dt);
  updateFires(dt);
  updateLaser();
  updateGun(dt);
  if (!state.third) {
    camera.position.x = Math.sin(state.viewBob) * .008;
    camera.position.y = Math.cos(state.viewBob * 2) * .008;
    camera.position.z = 0;
  }
  document.querySelector('#count').textContent = targets.filter(t => t.userData.alive).length;
  renderer.render(scene, camera);
}
animate();

