input.newString:
function cachedMat(color, roughness = .8) {
  const key = color + '|' + roughness;
  if (!matCache.has(key)) matCache.set(key, new THREE.MeshStandardMaterial({ color, roughness }));
  return matCache.get(key);
}
let flameTexture = null;
function getFlameTexture() {
  if (flameTexture) return flameTexture;
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(32, 34, 2, 32, 34, 31);
  g.addColorStop(0, 'rgba(255,255,235,1)');
  g.addColorStop(.35, 'rgba(255,220,120,.95)');
  g.addColorStop(.7, 'rgba(255,120,30,.55)');
  g.addColorStop(1, 'rgba(255,60,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 64);
  flameTexture = new THREE.CanvasTexture(c);
  flameTexture.colorSpace = THREE.SRGBColorSpace;
  return flameTexture;
}

